<?php
require __DIR__.'/../../app/bootstrap.php';
require __DIR__.'/../../app/services/Operations.php';
require __DIR__.'/../../app/services/AdminActions.php';
$u=require_login();$modules=require __DIR__.'/../../app/modules.php';
$titles=['dashboard'=>'Overview','reservations'=>'Reservations & events','customers'=>'Customers','venues'=>'Venues & tables','packages'=>'Event packages','products'=>'Products & supplies','inventory'=>'Stock movements','suppliers'=>'Suppliers','purchases'=>'Purchases','sales'=>'Sales & orders','payments'=>'Event payments','employees'=>'Employees','assignments'=>'Staff assignments','reports'=>'Business reports','alerts'=>'Notifications','users'=>'User accounts','audit'=>'Activity log','backup'=>'Database backup','settings'=>'Business settings'];
$page=is_string($_GET['page']??null)?$_GET['page']:'dashboard';if(!isset($titles[$page])||!allowed($page,$u)){http_response_code(403);exit('You do not have access to this module.');}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{admin_action($u,$page,$modules);flash('Saved successfully.');header('Location: ?page='.urlencode($page));exit;}catch(Throwable $e){$error=$e instanceof PDOException?'Unable to save. Check for duplicate records and valid linked items.':$e->getMessage();}}
$flash=$_SESSION['flash']??'';unset($_SESSION['flash']);
function input_field(string $name,string $label,string $type='text',mixed $value='',bool $required=true): void { echo '<label>'.esc($label);if($type==='textarea'){echo '<textarea name="'.esc($name).'" rows="3" '.($required?'required':'').'>'.esc((string)$value).'</textarea>';}else{echo '<input name="'.esc($name).'" type="'.esc($type).'" value="'.esc((string)$value).'" '.($required?'required':'').' '.($type==='number'?'min="0" step="1"':'').'>';}echo '</label>'; }
function select_field(string $name,string $label,array $options,mixed $value='',bool $required=true): void { echo '<label>'.esc($label).'<select name="'.esc($name).'" '.($required?'required':'').'>';foreach($options as $key=>$text)echo '<option value="'.esc((string)$key).'" '.((string)$key===(string)$value?'selected':'').'>'.esc((string)$text).'</option>';echo '</select></label>'; }
function choices(string $table,string $label='name',bool $optional=false): array { if(!in_array($table,['products','suppliers','employees','venues','packages','reservations'],true))return [];$rows=run('SELECT * FROM '.$table.($table==='reservations'?" WHERE status IN ('Pending','Confirmed','Completed')":' WHERE active=1'))->fetchAll();$out=$optional?[0=>'None / walk-in']:[''=>'Select an option'];foreach($rows as $r)$out[$r['id']]=$table==='reservations'?$r['reference'].' · '.$r['name']:$r[$label];return $out; }
function hidden(string $action): void { echo '<input type="hidden" name="csrf" value="'.esc($_SESSION['csrf']).'"><input type="hidden" name="action" value="'.esc($action).'">'; }
function table_view(array $rows,array $columns): void { echo '<div class="table-wrap"><table><thead><tr>';foreach($columns as $title)echo '<th>'.esc($title).'</th>';echo '</tr></thead><tbody>';if(!$rows)echo '<tr><td colspan="'.count($columns).'" class="empty">No records yet. Add your first record to get started.</td></tr>';foreach($rows as $r){echo '<tr>';foreach($columns as $key=>$title)echo '<td>'.esc((string)($r[$key]??'')).'</td>';echo '</tr>';}echo '</tbody></table></div>'; }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($titles[$page]) ?> · Uncorked</title><link rel="stylesheet" href="../assets/style.css"><link rel="stylesheet" href="../assets/admin.css"><script src="../assets/admin.js" defer></script></head><body class="admin-shell"><a class="skip" href="#content">Skip to content</a><aside class="sidebar"><a class="brand" href="?">uncorked<span>BEHIND THE GOOD TIMES</span></a><p class="side-label">WORKSPACE</p><nav aria-label="Business modules"><?php foreach($titles as $key=>$title):if(allowed($key,$u)): ?><a class="<?= $key===$page?'active':'' ?>" href="?page=<?= $key ?>" <?= $key===$page?'aria-current="page"':'' ?>><span class="nav-dot" aria-hidden="true"></span><?= esc($title) ?></a><?php endif;endforeach; ?></nav><div class="sidebar-bottom"><a href="../index.php">Public website ↗</a><form method="post"><?php hidden('logout'); ?><button>Sign out</button></form></div></aside><div class="admin-main"><header class="admin-top"><button class="sidebar-toggle" aria-label="Toggle navigation" aria-expanded="false">☰</button><span>UN CORk THE OCCASION / BUSINESS OPERATIONS</span><div><strong><?= esc($u['name']) ?></strong><small><?= esc($u['role']) ?></small></div></header><main id="content" class="workspace"><div class="page-heading"><div><p class="eyebrow"><?= date('l, F j, Y') ?></p><h1><?= esc($titles[$page]) ?></h1></div><a class="button small" href="?page=reservations">Reservation desk ↗</a></div><?php if($error): ?><div class="error" role="alert"><?= esc($error) ?></div><?php endif; ?><?php if($flash): ?><div class="success" role="status"><?= esc($flash) ?></div><?php endif; ?>
<?php require __DIR__.'/../../app/views.php'; ?>
